import time
import urllib.request
import urllib.error

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        max_retries_429 = 3
        retry_5xx = 1
        retry_network = 1

        # Handle 429 with exponential backoff
        for attempt in range(max_retries_429):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt == max_retries_429 - 1:
                        raise RateLimitError(f"Rate limit exceeded after {max_retries_429} attempts")
                    sleep_time = 0.5 * (2 ** attempt)
                    time.sleep(sleep_time)
                    continue
                elif 400 <= e.code < 500:
                    raise ClientError(f"Client error: {e.code}")
                elif 500 <= e.code < 600:
                    # Handle 5xx separately with single retry
                    pass
                else:
                    raise ClientError(f"Client error: {e.code}")
            except urllib.error.URLError:
                # Handle network errors separately
                pass

        # Handle 5xx with single retry
        for attempt in range(retry_5xx + 1):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if 500 <= e.code < 600:
                    if attempt == retry_5xx:
                        raise ServerError(f"Server error after {retry_5xx + 1} attempts")
                    time.sleep(1)
                    continue
                elif 400 <= e.code < 500:
                    raise ClientError(f"Client error: {e.code}")
                else:
                    raise ClientError(f"Client error: {e.code}")
            except urllib.error.URLError:
                # Network error, will be handled by network retry logic
                pass

        # Handle network errors with single retry
        for attempt in range(retry_network + 1):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.URLError:
                if attempt == retry_network:
                    raise ConnectionError(f"Connection failed after {retry_network + 1} attempts")
                time.sleep(1)
                continue

        # Fallback (should not reach here under normal circumstances)
        raise ConnectionError("Failed to retrieve response")
